//! Conformance with Python Jinja2.
//!
//! Every template in `tests/jinja2/templates` is rendered with the shared
//! context and compared byte for byte with the output real Jinja2 produced
//! (`tests/jinja2/expected`, regenerated by `make golden`). The filters,
//! tests and globals come from `tests/jinja2/filters.py`, which registers
//! them the way a Python Jinja2 application does and runs unchanged under
//! both engines.

use std::fs;
use std::path::Path;

use minijinja::value::Serde;
use minijinja::{Environment, Value};
use montyjinja::MontyJinja;

const ROOT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/jinja2");

fn env() -> Environment<'static> {
    let mut monty = MontyJinja::default();
    let filters = fs::read_to_string(Path::new(ROOT).join("filters.py")).unwrap();
    monty.add_module("filters.py", &filters).unwrap();
    let mut env = Environment::new();
    monty.install(&mut env);
    env.set_loader(minijinja::path_loader(Path::new(ROOT).join("templates")));
    env
}

#[test]
fn renders_like_python_jinja2() {
    let env = env();
    let json: serde_json::Value =
        serde_json::from_str(&fs::read_to_string(Path::new(ROOT).join("context.json")).unwrap()).unwrap();
    let context = Value::from(Serde(json));
    let mut failures = Vec::new();
    let mut names: Vec<_> = fs::read_dir(Path::new(ROOT).join("templates"))
        .unwrap()
        .map(|entry| entry.unwrap().file_name().into_string().unwrap())
        .collect();
    names.sort();
    for name in &names {
        let expected = fs::read_to_string(Path::new(ROOT).join("expected").join(name)).unwrap();
        let actual = env
            .get_template(name)
            .and_then(|tpl| tpl.render(&context))
            .unwrap_or_else(|err| format!("ERROR: {err:#}"));
        if actual != expected {
            failures.push(format!("--- {name}\njinja2: {expected:?}\nmonty:  {actual:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} templates differ:\n{}",
        failures.len(),
        names.len(),
        failures.join("\n")
    );
}

#[test]
fn in_place_mutation_is_an_error_not_a_silent_no_op() {
    let err = env()
        .render_str("{% set items = [1] %}{% do items.append(2) %}{{ items }}", ())
        .unwrap_err();
    assert!(
        err.to_string()
            .contains(".append() changes the sequence in place"),
        "{err}"
    );
    // Non-mutating methods on the same kinds are fine.
    let out = env()
        .render_str("{{ [3, 1, 3].count(3) }} {{ {'a': 1}.copy() }}", ())
        .unwrap();
    assert_eq!(out, "2 {'a': 1}");
}

#[test]
fn unknown_methods_report_pythons_attribute_error() {
    let err = env().render_str("{{ 'x'.nope() }}", ()).unwrap_err();
    assert_eq!(err.kind(), minijinja::ErrorKind::UnknownMethod);
    assert!(err.to_string().contains("AttributeError"), "{err}");
}

#[test]
fn compatibility_can_be_turned_off() {
    let mut env = Environment::new();
    MontyJinja::new(montyjinja::Config {
        jinja2_compat: false,
        ..montyjinja::Config::default()
    })
    .install(&mut env);
    let err = env.render_str("{{ 'x'.upper() }}", ()).unwrap_err();
    assert_eq!(err.kind(), minijinja::ErrorKind::UnknownMethod);
    assert!(env.render_str("{{ 'x'|truncate(1) }}", ()).is_err());
    assert_eq!(
        env.render_str("{{ 1e20 }}", ()).unwrap(),
        "100000000000000000000.0"
    );
}
